pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public {
        c = new C();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 seed) public {
        // admissible domain: any caller must itself be a contract exposing the
        // correct supportsToken(); we route through our attacker helper and let
        // the fuzzed seed decide whether it re-enters airDrop.
        bool reenter = (bound(seed, 0, 999) % 2 == 0);
        att.setReenter(reenter);
        bool ok;
        try att.attack() {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            // exactly one +20 grant per completed airDrop
            assertTrue(c.tokenBalance(address(att)) == 20);
        } else {
            // reverted: no grant
            assertTrue(c.tokenBalance(address(att)) == 0);
        }
    }
}

contract Attacker {
    C public target;
    bool public reenter;
    uint256 public depth;

    constructor(C _c) {
        target = _c;
    }

    function setReenter(bool r) external {
        reenter = r;
        depth = 0;
    }

    function attack() external {
        depth = 0;
        target.airDrop();
    }

    function supportsToken() external returns (bytes32) {
        if (reenter && depth == 0) {
            depth = 1;
            try target.airDrop() {} catch {}
            depth = 0;
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

