pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 salt) public {
        vm.assume(salt < type(uint128).max);
        vm.warp(salt);

        // Adversarial counterparty: the caller is a Bank whose supportsToken
        // callback re-enters airDrop through a distinct proxy contract, so the
        // nested grant is credited to a DIFFERENT key (the proxy), not the caller.
        Proxy proxy = new Proxy(c);
        ReentrantCaller caller = new ReentrantCaller(c, proxy);

        vm.prank(address(caller));
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }

        // General rule: a single airDrop by any caller may credit only the
        // caller's own key; every other key's balance must remain untouched.
        // P: nested airDrop reverts (lock held) -> proxy balance stays 0 (outer
        // call may revert too, but the invariant still holds).
        // M: lock never set -> nested airDrop succeeds -> proxy key credited 20.
        assertTrue(c.tokenBalance(address(proxy)) == 0, "no third-party key may gain balance from one airDrop");
        ok; // silence unused warning
    }
}

contract BankBase {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

contract Proxy is BankBase {
    C c;
    constructor(C _c) { c = _c; }
    function nest() external { c.airDrop(); }
}

contract ReentrantCaller is BankBase {
    C c;
    Proxy proxy;
    constructor(C _c, Proxy _p) { c = _c; proxy = _p; }

    function supportsToken() external override returns (bytes32) {
        // re-entrant call during the outer airDrop's modifier check
        proxy.nest();
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

