pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bool doReenter) public {
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        attacker.setReenter(doReenter);
        attacker.airDrop();
        // Universal rule: a completed airDrop grants exactly one +20 credit;
        // reentrant attempts are always blocked by the lock.
        assertTrue(c.tokenBalance(address(attacker)) == 20);
    }
}

contract ReentrantAttacker {
    C public c;
    bool public reenter;
    bool private attacking;

    constructor(C _c) { c = _c; }

    function setReenter(bool b) external { reenter = b; }

    function airDrop() external { c.airDrop(); }

    function supportsToken() external returns (bytes32) {
        if (reenter && !attacking) {
            attacking = true;
            // try to re-enter airDrop during the supportsToken check;
            // with the lock intact this reverts and is swallowed
            try c.airDrop() {} catch {}
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

