pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function testFuzz_property(uint256 rounds, uint256 seed) public {
        rounds = bound(rounds, 1, 10);
        address who = address(uint160(1 + (seed % type(uint160).max - 1)));
        for (uint256 i = 0; i < rounds; i++) {
            caller.drop(c, who);
        }
        assertTrue(c.tokenBalance(who) <= 20);
    }
}

contract Caller {
    function drop(C c, address who) external {
        vmPrankFree(c, who);
    }

    function vmPrankFree(C c, address) internal {
        try c.airDrop() {} catch {}
    }
}

