pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address seed) public {
        // Drive airDrop through an adversarial-caller helper: only a CONTRACT whose
        // supportsToken() returns keccak("Nu Token") can legitimately pass the modifier.
        // The fuzzer's `seed` merely feeds the domain; the helper is the admissible caller.
        GoodCaller caller = new GoodCaller(c);
        bool ok;
        address callerAddr = address(caller);
        // assert the general rule: any legitimate Bank-compatible caller that airDrops
        // must end up with exactly 20 tokens credited to itself
        assertTrue(
            c.tokenBalance(callerAddr) == 20,
            "legitimate airDrop caller must be credited 20 tokens"
        );
    }
}

contract GoodCaller {
    constructor(C t) {
        t.airDrop();
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
